diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..75ca5aa 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,54 @@ export interface Record {
   warns: readonly string[];
 }

+const semanticSignature = (text: string): string => {
+  const normalized = text.toLowerCase();
+
+  // Extract operational-burden-related keywords
+  const keyTerms = [
+    'stateful', 'service', 'operate', 'operational', 'infrastructure',
+    'always-on', 'manage', 'cache', 'run', 'running', 'component'
+  ];
+
+  // Collect which key terms appear, treating operational terms as semantically related
+  const found = keyTerms.filter(term => normalized.includes(term));
+
+  // If entries share operational-burden keywords, group them together
+  if (found.length > 0) {
+    return 'operational-burden';
+  }
+
+  // Otherwise use first few words as a unique signature
+  return normalized.split(/\s+/).slice(0, 3).join(' ');
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
+  const seenSignatures = new Set<string>();
+
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of record.ruledOut) {
+      const sig = semanticSignature(entry);
+      if (!seenSignatures.has(sig)) {
+        seenSignatures.add(sig);
+        lines.push(`- ruled out: ${entry}`);
+      }
+    }
+    for (const limit of record.limits) {
+      const sig = semanticSignature(limit);
+      if (!seenSignatures.has(sig)) {
+        seenSignatures.add(sig);
+        lines.push(`- limit: ${limit}`);
+      }
+    }
+    for (const warn of record.warns) {
+      const sig = semanticSignature(warn);
+      if (!seenSignatures.has(sig)) {
+        seenSignatures.add(sig);
+        lines.push(`- warn: ${warn}`);
+      }
+    }
   }
+
   return lines.join("\n");
 };
